CREATE TABLE IF NOT EXISTS movie (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title VARCHAR(120) NOT NULL, language VARCHAR(40), duration_minutes INT);
CREATE TABLE IF NOT EXISTS theatre (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(120) NOT NULL, city VARCHAR(80) NOT NULL);
CREATE TABLE IF NOT EXISTS screen (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, theatre_id BIGINT NOT NULL REFERENCES theatre(id), screen_name VARCHAR(50) NOT NULL);
CREATE TABLE IF NOT EXISTS seat (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, screen_id BIGINT NOT NULL REFERENCES screen(id), seat_number VARCHAR(10) NOT NULL, UNIQUE(screen_id, seat_number));
CREATE TABLE IF NOT EXISTS show_schedule (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, movie_id BIGINT NOT NULL REFERENCES movie(id), screen_id BIGINT NOT NULL REFERENCES screen(id), show_date DATE NOT NULL, show_time TIME NOT NULL, ticket_price DECIMAL(8,2) NOT NULL);
CREATE TABLE IF NOT EXISTS booking (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, booking_reference VARCHAR(30) NOT NULL UNIQUE, customer_name VARCHAR(100) NOT NULL, show_id BIGINT NOT NULL REFERENCES show_schedule(id), status VARCHAR(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS booking_seat (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, booking_id BIGINT NOT NULL REFERENCES booking(id), show_id BIGINT NOT NULL REFERENCES show_schedule(id), seat_id BIGINT NOT NULL REFERENCES seat(id), UNIQUE(show_id, seat_id));
CREATE TABLE IF NOT EXISTS payment_record (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, booking_id BIGINT NOT NULL REFERENCES booking(id), amount DECIMAL(8,2) NOT NULL, payment_status VARCHAR(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
